"""Supplementary Tables 1-6 for Paper A, written from the analysis JSON files. The tables are built below in the order T[1]..T[7] (no T[6])
and published under the numbers in NUM (order of first citation in the paper); the sensitivity table (T[7], published as
Table S2) is written by nc_si_sensitivity.py and only collected here.
Outputs tables/Table_S*.csv, tables/Supplementary_Tables.xlsx (one sheet per table, legend in row 1) and tables/legends.md.
"""
import json, os, numpy as np, pandas as pd
os.makedirs("tables",exist_ok=True)
T={}; LEG={}
NUM={1:3,2:1,3:6,4:4,5:5,7:2}            # build order -> published Supplementary Table number (the two-city table, build 6, was dropped 2026-11-08)
# ---- Table S1: data and validation
_TR = json.load(open("nc_si_transfer.json"))
SRC={'USACE NACCS (TR-15-5; CHS save points)': ('USACE Coastal Hazards System, chs.erdc.dren.mil (registration); ERDC/CHL TR-15-5 Fig. 8-19', 'NACCS 2015 products; CHS download 2026'), 'NOAA CUDEM': ('NOAA NCEI CUDEM 1/9 arc-second, Northeast Sandy tiles', '2014 release, updated; accessed 2026'), 'NOAA SLOSH MOM v4 + STORM': ('NOAA NHC SLOSH MOM v4 (national); STORM synthetic set (Bloemendaal et al. 2020)', 'MOM v4 2026-06-17; STORM v3'), 'NYC DEP Stormwater Flood Maps': ('NYC Open Data 9i7c-xyvv (file geodatabases)', 'published 2024 (plan 2021); accessed 2026'), 'NOAA Atlas 14 vol. 10': ('NOAA HDSC Precipitation Frequency Data Server, Central Park (version 3)', '2015, revised 2019; accessed 2026'), 'FloodNet (events aq7i-eu5q; sensors kb2e-tjy3)': ('NYC Open Data: flood events aq7i-eu5q; sensors kb2e-tjy3', '2020-11 to 2026-08'), 'NOAA MRMS 1-h QPE Pass 2': ('Iowa State mtarchive, MultiSensor_QPE_01H_Pass2', '1,172 UTC days 2020–2026; 152 archive gaps'), 'NYC 311 street-flooding complaints': ("NYC Open Data erm2-nwe9, descriptor 'Street Flooding (SJ)'", '2020-01 to 2026-09'), 'NOAA sea-level-rise inundation (NY metro)': ('NOAA Office for Coastal Management Sea Level Rise Data (InPort 48106), NY_M block, MHHW +0–6 ft', 'accessed 2026'), 'NOAA CO-OPS 8518750 (The Battery)': ('NOAA Tides & Currents station 8518750, datums and verified water levels', 'tidal epoch 1983–2001; accessed 2026'), 'USGS/NYC Sandy Inundation Zone (5xsi-dfpx)': ('NYC Open Data 5xsi-dfpx (NYC SBS; from the FEMA MOTF field-verified surge extent)', 'FEMA MOTF 2013; portal 2015'), 'FEMA NFHL, effective and 2015 preliminary': ('hazards.fema.gov NFHL (effective) and Prelim_NFHL, DFIRM 360497 (30 Jan 2015)', 'accessed 2026-09/10'), 'ASOS 1-minute precipitation (LGA, JFK, EWR)': ('Iowa Environmental Mesonet ASOS 1-minute archive', '2020-11 to 2026-08'), 'USACE NSI': ('USACE National Structure Inventory API, counties 36005/36047/36061/36081/36085', '2026 Base; accessed 2026'), 'NYC PLUTO (64uk-42ks)': ('NYC Open Data 64uk-42ks (PLUTO)', '2026 release'), 'USACE EGM 01-03 / 04-01': ('USACE Economic Guidance Memoranda 01-03 (2000) and 04-01 (2003), tabulated functions', '–'), 'MTA stations, entrances, GTFS': ('data.ny.gov 39hk-dx4f (stations), i9wp-a4ja (entrances); MTA GTFS static feed', 'accessed 2026'), 'OpenFEMA NFIP Policies, Claims': ('OpenFEMA NFIP Redacted Policies v3 (NfipPolicies) and NFIP Redacted Claims v3 (NfipClaims); filtered on censusGeoid', 'policies effective ≤2026-09-21 and terminating ≥2026-08-01; claims 2012-10/11'), 'HUD/CDBG tract eligibility (qmcw-ur37)': ('NYC Open Data qmcw-ur37 (NYC DCP, from HUD LMISD 2016–2020)', 'accessed 2026'), 'Pratt Center (2008); City of New York (2021)': ("Sheth & Neuwirth, New York's Housing Underground (Pratt Center, Chhaya CDC); The New Normal (p. 47)", '2008; 2021'), 'Census TIGER 2020': ('US Census TIGER/Line 2020 block groups, New York (tl_2020_36_bg)', '2021 release')}
rows=[
("USACE NACCS (TR-15-5; CHS save points)","Still-water-level return periods, storm rates, per-storm peaks, bias/uncertainty","18,977 points; 1–10,000 yr","Surge frequency","Sandy = 1-in-140; Jamaica Bay offset −0.17 to −0.37 m, AAI effect −2.3%"),
("NOAA CUDEM","Ground elevation, NAVD88","1/9 arc-sec → 20 m, 55 m","Inundation surface","Datum error found and fixed (33 m); connected bathtub vs Sandy footprint within the five boroughs POD 93%, FAR 19%, CSI 0.76"),
("NYC DEP Stormwater Flood Maps","Hydraulic-model rainfall footprints, two depth classes","3 scenarios (1.77/2.13/3.66 in h⁻¹)","Rainfall extent","Limited scenario unreadable; Extreme tied to 2080 sea level; 68% of FloodNet sensors inside 8.3% of land (siting bias 8.1×)"),
("NOAA Atlas 14 vol. 10","Rainfall frequency at Central Park, 5 min to 60 days","1–1,000 yr","Return periods of DEP scenarios and the design intensity","1.75 in h⁻¹ is ≈1-in-7 yr over 60 min but ≈ annual over 30 min; DEP labels its scenarios 10 and 100 yr"),
("FloodNet (events aq7i-eu5q; sensors kb2e-tjy3)","Street water-depth events","479 sensors, 1-min, 2020–","Observed flood frequency, tidal share","Sited at expected trouble spots (8.1×); the borough-average rate transfers (predicted/observed %.2f); 22 events without rain evidence and 1 at an unlisted sensor removed; 3 sensors reclassified as tidal"%(_TR["lobo"]["any"]["all"]["ratio"])),
("NOAA MRMS 1-h QPE Pass 2","Radar–gauge rainfall","1 km, hourly, 1,172 days","Rain at each sensor and lot","Heavy hours more frequent in 2020–2026 than long-run; rainy days rescaled by bin to Atlas 14 and gauge rates"),
("NYC 311 street-flooding complaints","Complaint location and date","21,287 records, 2020–","Observation-bias tests","Used only to test the flood duration criterion and sensor siting"),
("NOAA sea-level-rise inundation (NY metro)","Mean higher high water + 0–6 ft, hydrologically connected","3 m → 55 m","Tidal reach and sea-level-rise steps","Not coupled to surge; no groundwater"),
("NOAA CO-OPS 8518750 (The Battery)","Datums, water-level record since 1920","6-min","Datum conversion, Sandy peak","Trend +2.9 mm yr⁻¹"),
("USGS/NYC Sandy Inundation Zone (5xsi-dfpx)","Field-verified 2012 footprint","polygon","Validation","–"),
("FEMA NFHL, effective and 2015 preliminary","Special Flood Hazard Area polygons","8,009 effective polygons","Flood-map coverage","Rain area outside: 93% (effective) vs 86% (preliminary); 62 policies per 100 structures inside the effective flood zone, 2 outside"),
("ASOS 1-minute precipitation (LGA, JFK, EWR)","Sub-hourly rain at three airports","1 min; 1,099–1,258 complete days per gauge","Sub-hourly check of the design comparison","Gauges 5–20 km from most sensors; ratios applied to radar hourly maxima"),
("USACE NSI","Per-structure value, storeys, occupancy, foundation, first-floor height","881,621 structures","Exposure","Median USD 176 per sq ft vs PLUTO USD 400; valuation sampled σ = 0.25"),
("NYC PLUTO (64uk-42ks)","Tax lots, basement code, building class","858,602 lots","Basement layer; working-model exposure","Basement code is structural, not occupancy"),
("USACE EGM 01-03 / 04-01","Generic depth-damage functions","1 ft steps, ±SD","Vulnerability","Untuned Sandy loss within the observed range (0.85 of the central direct value)"),
("MTA stations, entrances, GTFS","Station structure type, entrances, alignments","496 / 2,120 / routes","Subway layer","Vents and depths not public"),
("OpenFEMA NFIP Policies, Claims","In-force policies, Sandy claims","block group; 36,961 contracts","Insurance","Coordinates redacted to 0.1° → upper bound; Sandy claims identical in v2 and v3; realised 9.4%"),
("HUD/CDBG tract eligibility (qmcw-ur37)","Low/moderate-income share by tract","2,327 tracts","Income split; basement allocation","Proxy for income"),
("Pratt Center (2008); City of New York (2021)","Unauthorized units citywide (1990–2000 census vs certificate-of-occupancy gap); illegal basement apartments","114,000; ≥50,000","Informal-unit allocation (upper and lower bound)","114,000 is not basement-specific; allocation rule moves counts ≤15% (surge), 1% (rain)"),
("Census TIGER 2020","Block-group geometry","–","Joins","–")]
rows=[(r[0],r[1],r[2],r[3],r[4],*SRC[r[0]]) for r in rows]
T[1]=pd.DataFrame(rows,columns=["Dataset","What it gives","Resolution / period","Role","Validation or known bias","Source / identifier","Version / period accessed"])
LEG[1]="Supplementary Table 1 | Input data, sources and the check applied to each. Every input is a public product; identifiers are NYC Open Data / data.ny.gov / OpenFEMA dataset codes or provider names. The validation column reports the comparison or bias documented in Methods; 'upper bound' and 'comparison only' mark inputs whose limitation is stated in the text."
# ---- Table S2: impact by return period on one water-level axis
f2=json.load(open("fig2_impact_rp.json"))
T[2]=pd.DataFrame({"Return period (yr)":f2["rp"],"Still-water level (m NAVD88)":f2["wl_navd"],"Structure loss (USD bn)":f2["loss_bn"],"Basement lots":f2["basement_lots"],"Informal units, 114,000 allocated (upper bound)":[round(x) for x in f2["informal_units"]],"Informal units, 50,000 allocated (lower bound)":[round(x*50000/114000) for x in f2["informal_units"]],"Underground stations":f2["underground_stations"],"Station entrances":f2["entrances"]})
LEG[2]="Supplementary Table 2 | Impact by surge return period on one still-water axis (Fig. 2). Water levels are the NACCS Battery curve converted to NAVD88; footprints are the connected bathtub on the 20 m DEM at present-day sea level with no defences. Structure loss uses NSI exposure and USACE generic depth-damage functions; basement lots are small-residential lots with a below-grade basement (PLUTO); informal units allocate the citywide estimate of unauthorised units (upper bound) or the city's figure for basement apartments (lower bound) uniformly to basement lots; stations and entrances are MTA underground stations and their street entrances inside the footprint."
# ---- Table S3: pluvial-only vs surge-side block groups
p3=json.load(open("pluvial_insurance_nsi.json")); rows=[]
for scen,d in p3.items():
    for grp,v in d.items(): rows.append(dict(Scenario=scen,Group={'pluvial-only BGs':'rain-side block groups','surge-side BGs':'surge-side block groups','outside surge domain BGs':'block groups outside the surge model','all':'all'}[grp],**{"Building loss (USD bn)":round(v["loss_bn"],2),"Share of scenario loss (%)":round(v["loss_share_pct"],1),"Block groups":v["bgs"],"Block groups with no policy":v["bgs_nopolicy"],"Contracts in block groups":v["contracts_in_bgs"],"Share of city contracts (%)":round(v["contract_share_pct"],1),"Upper-bound insurable share (%)":round(v["upper_pct"],1),"Expected insurable share (%)":round(v["expected_pct"],1)}))
T[3]=pd.DataFrame(rows)
LEG[3]="Supplementary Table 3 | NFIP cover against rainfall building loss, surge-side versus rain-side block groups (data for Fig. 3b). Loss is computed on the DEP stormwater footprints (moderate ≈1-in-18 yr, extreme ≈1-in-458 yr) with the NSI × USACE loss chain. A block group is surge-side if at least half of its structure value lies inside the 1-in-1,000-yr still-water reach and rain-side otherwise; block groups with less than half of their structure value inside the surge model domain are reported separately. Upper bound = min(block-group loss, block-group building cover); expected = take-up × min(structure loss, mean cover per contract) with policies placed at random in the block group. The extreme scenario is tied to 2080 sea level in the DEP model."
# ---- Table S4: Monte Carlo settings and percentiles
mc=json.load(open("paper_a_mc.json")); core=json.load(open("paper_a_core.json"))
T[4]=pd.DataFrame([
("Hazard-curve digitisation","Uniform ±0.10 m shift of the NACCS still-water curve","",""),
("Structure valuation","Lognormal multiplier on all NSI values, σ = 0.25 (PLUTO/NSI ratio 1.84 ≈ 2.4σ)","",""),
("Vulnerability family","USACE generic (EGM 01-03/04-01) or storey-fraction curve, equal weight","",""),
("USACE function scaling","Triangular 0.76–1.00–1.15 (observed structure-only Sandy loss USD 8.0–12.1 bn ÷ untuned USD 10.48 bn) × N(1, 0.03) tabulated-function noise","",""),
("Storey-curve scaling","Triangular 0.92–1.00–1.08 on k = %.2f (recalibrated on NSI values)"%core["sandy"]["k_nsi"],"",""),
("Not sampled (stated)","No coastal defences in the bathtub; single Battery curve (checked, −2.3%); present-day sea level","",""),
("Draws","%d"%mc["n"],"",""),
("Result: USACE point estimate","","485","USD million a year"),
("Result: median","","%.0f"%mc["q50"],"USD million a year"),
("Result: interquartile range","","%.0f–%.0f"%(mc["q25"],mc["q75"]),"USD million a year"),
("Result: 5–95% range","","%.0f–%.0f"%(mc["q05"],mc["q95"]),"USD million a year")],columns=["Item","Specification","Value","Unit"])
LEG[4]="Supplementary Table 4 | Monte Carlo propagation of uncertainty in the surge annual loss. Per-structure depths at the 29 water levels are precomputed once; each draw is a vector operation over the 120-point exceedance grid. The three structural choices listed as 'not sampled' are held fixed; the storey-share rule is varied separately in Extended Data Fig. 2i."
# ---- Table S5: gap decomposition and counterfactuals
g=json.load(open("fig5_gap_nsi.json")); pct=lambda d,k: round(100*d[k]/d["loss"],1); rows=[]
for rp,d in g["events"].items(): rows.append({"Event":f"1-in-{rp} yr","Loss (USD bn)":round(d["loss"]/1e9,2),"Paid, upper bound (%)":pct(d,"upper"),"Paid, expected (%)":pct(d,"neutral"),"Gap: no policy (%)":pct(d,"nopolicy"),"Gap: cover < loss (%)":pct(d,"cap"),"Full take-up, local cover (%)":pct(d,"full_local"),"Full take-up, statutory cap (%)":pct(d,"full_stat")})
d=g["aai"]; rows.append({"Event":"Annual average (AAI)","Loss (USD bn)":round(d["loss"]/1e9,3),"Paid, upper bound (%)":pct(d,"upper"),"Paid, expected (%)":pct(d,"neutral"),"Gap: no policy (%)":pct(d,"nopolicy"),"Gap: cover < loss (%)":pct(d,"cap"),"Full take-up, local cover (%)":pct(d,"full_local"),"Full take-up, statutory cap (%)":pct(d,"full_stat")})
for grp,d in g["aai_by_lmi"].items(): rows.append({"Event":f"AAI, tract LMI share {grp}","Loss (USD bn)":round(d["loss"]/1e9,3),"Paid, upper bound (%)":pct(d,"upper"),"Paid, expected (%)":pct(d,"neutral"),"Gap: no policy (%)":pct(d,"nopolicy"),"Gap: cover < loss (%)":pct(d,"cap"),"Full take-up, local cover (%)":pct(d,"full_local"),"Full take-up, statutory cap (%)":pct(d,"full_stat"),"Take-up in 100-yr footprint (%)":round(100*g["takeup_100yr_by_lmi"][grp],1)})
T[5]=pd.DataFrame(rows)
LEG[5]="Supplementary Table 5 | Decomposition of the NFIP shortfall and counterfactuals (Fig. 4; Supplementary Fig. 3). Loss on the NSI × USACE × NACCS basis; %d contracts. Upper bound = min(block-group loss, block-group cover). Expected = take-up × min(structure loss, mean cover per contract). Gap: no policy = (1 − take-up) × loss; gap: cover < loss = take-up × max(loss − cover, 0). Counterfactuals: every structure covered at its block group's mean cover per contract, or at the statutory limit ($250,000 per residential unit, $500,000 non-residential). LMI groups are tract quartiles of the HUD/CDBG low-to-moderate-income population share; take-up is contracts per NSI structure inside the 1-in-100-yr footprint."%g["contracts"]
# ---- Table S7: sensitivity of the headline numbers (computed by nc_si_sensitivity.py)
T[7]=pd.read_csv(f"tables/Table_S{NUM[7]}.csv")
LEG[7]="Supplementary Table 7 | Sensitivity of the headline numbers. Rainfall footprint outside the flood zone on the effective FIRM, the 2015 preliminary FIRM, either map and the modelled 1-in-100-yr reach, for the extreme (2080 sea level) and moderate (current sea level) rainfall scenarios; sensor-clustered bootstrap interval for the share of flood days below 1.75 in/h; the rain-side and surge-side split at 25, 50 and 75% of structure value inside the 1-in-100 or 1-in-1,000-yr reach; NFIP take-up and tidal sensors on the preliminary map."
# ---- write
with pd.ExcelWriter("tables/Supplementary_Tables.xlsx",engine="openpyxl") as xw:
    for i in sorted(NUM,key=NUM.get):
        n=NUM[i]; LEG[i]=LEG[i].replace(f"Supplementary Table {i} |",f"Supplementary Table {n} |")
        if i<7: T[i].to_csv(f"tables/Table_S{n}.csv",index=False)
        pd.DataFrame([[LEG[i]]]).to_excel(xw,sheet_name=f"Table S{n}",index=False,header=False,startrow=0)
        T[i].to_excel(xw,sheet_name=f"Table S{n}",index=False,startrow=2)
open("tables/legends.md","w").write("\n\n".join(LEG[i] for i in sorted(NUM,key=NUM.get))+"\n")
for i in sorted(NUM,key=NUM.get): print(f"Table S{NUM[i]}: {T[i].shape[0]} rows x {T[i].shape[1]} cols")
print("saved tables/")
